export function getPoseImageUrl(poseNameOrId) {
  if (!poseNameOrId) return null;
  
  // 1. Direct match by exact key
  if (POSE_IMAGE_MAPPING[poseNameOrId]) {
    return `/poses/${POSE_IMAGE_MAPPING[poseNameOrId]}`;
  }
  
  // 2. Soft matching on lowercase alphanumeric keys
  const target = poseNameOrId.toLowerCase().replace(/[^a-z0-9]/g, '');
  for (const [key, value] of Object.entries(POSE_IMAGE_MAPPING)) {
    const stdKey = key.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (stdKey === target || target.includes(stdKey) || stdKey.includes(target)) {
      return `/poses/${value}`;
    }
  }
  
  // 3. Fallback placeholder
  return `https://placehold.co/800x600/13131a/c4a96a?text=${encodeURIComponent(poseNameOrId)}&font=Playfair+Display`;
}
